// Validates and normalizes the intake payload from Fluent Forms.
// Fails loudly with a descriptive error if a required field is missing —
// a silent failure here would create a broken Clio contact with blank data.
const raw = $input.first().json.body || $input.first().json;

const required = ['full_name', 'email', 'matter_type'];
for (const field of required) {
  if (!raw[field] || String(raw[field]).trim() === '') {
    throw new Error(`Intake sync: missing required field '${field}'. Check the Fluent Forms field mapping.`);
  }
}

// Practice-area label mapping — edit to match your Clio instance's exact practice area names.
const MATTER_TYPE_MAP = {
  'family law': 'Family Law',
  'estate planning': 'Estate Planning',
  'personal injury': 'Personal Injury',
  'business law': 'Business Law',
  'criminal defense': 'Criminal Defense',
};
const rawType = String(raw.matter_type).trim().toLowerCase();
const practice_area = MATTER_TYPE_MAP[rawType] || String(raw.matter_type).trim();

// Normalize phone to E.164 (US default) if provided.
let phone = String(raw.phone || '').replace(/[^0-9+]/g, '');
if (phone && !phone.startsWith('+')) {
  phone = phone.length === 10 ? `+1${phone}` : `+${phone}`;
}

return [{ json: {
  full_name: String(raw.full_name).trim(),
  email: String(raw.email).trim().toLowerCase(),
  phone,
  practice_area,
  case_details: String(raw.case_details || '').trim(),
  referral_source: String(raw.referral_source || '').trim(),
  submitted_at: new Date().toISOString(),
} }];

// Determines whether a matching contact already exists in Clio.
const response = $input.first().json;
const contacts = response.data || [];
const intake = $('Validate And Normalize Intake Data').first().json;

const match = contacts.find(c => (c.primary_email_address || '').toLowerCase() === intake.email);

return [{ json: {
  ...intake,
  contact_exists: !!match,
  existing_contact_id: match ? match.id : null,
} }];

const created = $input.first().json;
const intake = $('Check If Contact Exists').first().json;
if (!created.data || !created.data.id) {
  throw new Error('Intake sync: Clio contact creation returned no id — check the Clio API response and credential scope.');
}
return [{ json: { ...intake, contact_id: created.data.id } }];

const matter = $input.first().json.data;
const intake = $('Check If Contact Exists').first().json;

let contact_id = null;
try { contact_id = $('Extract New Contact Id').first().json.contact_id; } catch (e) {}
if (!contact_id) {
  try { contact_id = $('Use Existing Contact Id').first().json.contact_id; } catch (e) {}
}

return [{ json: {
  matter_id: matter.id,
  contact_id,
  full_name: intake.full_name,
  email: intake.email,
  phone: intake.phone,
  practice_area: intake.practice_area,
  case_details: intake.case_details,
  referral_source: intake.referral_source,
} }];

