// Builds the optional client confirmation message.
// This node only prepares text — actual sending is gated behind the OPS1 compliance guardrail.
const d = $('Build PM Notification Message').first().json;
const message = `Hi ${d.full_name.split(' ')[0]}, thanks for reaching out about your ${d.practice_area} matter. Our team has received your information and will follow up shortly.`;
return [{ json: {
  ...d,
  channel: 'email',
  recipient: d.email,
  message,
  template_id: 'PAC-20',
} }];
